// Extrai e processa a tabela CSV de investimentos
const csvData = $input.first().json.data || $input.first().json.body || '';
const lines = (typeof csvData === 'string' ? csvData : '').trim().split('\n');

if (lines.length <= 1) {
  // Fallback caso a requisição externa falhe
  return [
    { json: { perfil: 'Conservador', produto: 'Tesouro Selic', minimo: 500, rentabilidade: '13.0%' } },
    { json: { perfil: 'Conservador', produto: 'CDB Liquidez Diária', minimo: 1000, rentabilidade: '12.5%' } },
    { json: { perfil: 'Moderado', produto: 'CDB Prefixado', minimo: 1000, rentabilidade: '14.0%' } },
    { json: { perfil: 'Moderado', produto: 'Fundo Multimercado', minimo: 5000, rentabilidade: '16.0%' } },
    { json: { perfil: 'Arrojado', produto: 'Ações ETF', minimo: 500, rentabilidade: 'Variável' } },
    { json: { perfil: 'Arrojado', produto: 'Fundo de Ações', minimo: 10000, rentabilidade: 'Variável' } }
  ];
}

const headers = lines[0].split(',').map(h => h.trim());
const items = [];

for (let i = 1; i < lines.length; i++) {
  const row = lines[i].split(',').map(r => r.trim());
  if (row.length === headers.length) {
    const obj = {};
    headers.forEach((header, index) => {
      let val = row[index];
      if (header === 'minimo') val = parseFloat(val) || 0;
      obj[header] = val;
    });
    items.push({ json: obj });
  }
}

return [
  {
    json: {
      investimentos: items.map(item => item.json)
    }
  }
];

// Cruzamento do Perfil do Cliente com os Produtos do CSV
const cliente = $('Split Out Clientes').item.json;
const investimentos = $('Code - Parse CSV Investimentos').all().map(i => i.json);

// Sanitiza saldo monetário (ex: 'R$ 12.500,00' -> 12500.00)
let saldoNumerico = 0;
if (typeof cliente.saldo === 'number') {
  saldoNumerico = cliente.saldo;
} else if (typeof cliente.saldo === 'string') {
  const limpo = cliente.saldo.replace(/[^0-9,-]/g, '').replace(',', '.');
  saldoNumerico = parseFloat(limpo) || 0;
}

// Filtra produtos aderentes ao perfil
const perfilCliente = (cliente.perfil || '').trim().toLowerCase();
const produtosCompativeis = investimentos.filter(inv => {
  const perfilInv = (inv.perfil || '').trim().toLowerCase();
  return perfilInv === perfilCliente;
});

// Seleciona as melhores recomendações (que cabem no saldo ou prioritárias)
const recomendados = produtosCompativeis.filter(p => p.minimo <= saldoNumerico);
const produtosFinais = recomendados.length > 0 ? recomendados : produtosCompativeis;

return {
  json: {
    cliente_nome: cliente.nome,
    cliente_email: cliente.email,
    cliente_saldo: cliente.saldo,
    cliente_saldo_num: saldoNumerico,
    cliente_perfil: cliente.perfil,
    produtos_recomendados: produtosFinais,
    produtos_resumo: produtosFinais.map(p => `${p.produto} (Mín: R$ ${p.minimo} | Retorno: ${p.rentabilidade})`).join('; '),
    data_analise: new Date().toLocaleDateString('pt-BR')
  }
};

