// Nó Híbrido: Captura a resposta da IA ou gera template estático robusto (Fallback MVP)
const dadosCruzados = $('Code - Cruzar Perfil e Investimentos').item.json;
let mensagemFinal = '';

// Verifica se o agente de IA gerou conteúdo
try {
  const aiOutput = $input.first()?.json?.output || $input.first()?.json?.text;
  if (aiOutput && typeof aiOutput === 'string' && aiOutput.trim().length > 20) {
    mensagemFinal = aiOutput.trim();
  }
} catch (e) {
  // Continua para fallback
}

// Template dinâmico caso a IA não tenha executado (Modo MVP)
if (!mensagemFinal) {
  const primeiroNome = dadosCruzados.cliente_nome.split(' ')[0];
  const perfil = dadosCruzados.cliente_perfil;

  if (perfil === 'Conservador') {
    mensagemFinal = `Olá, ${primeiroNome}! Identificamos que seu perfil de investidor é Conservador com saldo disponível de ${dadosCruzados.cliente_saldo}. Para proteger seu patrimônio com máxima segurança e liquidez, recomendamos alocações em ${dadosCruzados.produtos_resumo}. Conte com a DIO Investimentos para planejar seu futuro!`;
  } else if (perfil === 'Moderado') {
    mensagemFinal = `Olá, ${primeiroNome}! Com base no seu perfil Moderado e saldo de ${dadosCruzados.cliente_saldo}, selecionamos alternativas que equilibram rentabilidade e previsibilidade: ${dadosCruzados.produtos_resumo}. Uma excelente estratégia para acelerar seus objetivos!`;
  } else {
    mensagemFinal = `Olá, ${primeiroNome}! Seu perfil Arrojado e capital de ${dadosCruzados.cliente_saldo} abrem portas para opções de alto potencial de retorno no mercado. Selecionamos para sua carteira: ${dadosCruzados.produtos_resumo}. Vamos potencializar seus resultados!`;
  }
}

// Monta HTML elegante para briefing por e-mail
const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 8px; overflow: hidden;">
  <div style="background: #0f172a; color: #ffffff; padding: 24px; text-align: center;">
    <h2 style="margin: 0; color: #38bdf8;">DIO Asset Management</h2>
    <p style="margin: 4px 0 0 0; font-size: 14px; opacity: 0.8;">Assessoria Patrimonial Inteligente</p>
  </div>
  <div style="padding: 24px; background: #ffffff;">
    <p style="font-size: 16px; line-height: 1.6; color: #334155;">${mensagemFinal.replace(/\n/g, '<br>')}</p>
    <div style="margin: 20px 0; padding: 16px; background: #f8fafc; border-left: 4px solid #38bdf8; border-radius: 4px;">
      <strong>Perfil:</strong> ${dadosCruzados.cliente_perfil} | <strong>Saldo:</strong> ${dadosCruzados.cliente_saldo}
    </div>
    <p style="font-size: 13px; color: #64748b; margin-top: 24px;">Esta é uma simulação gerada de forma automatizada via RPA + n8n + Inteligência Artificial.</p>
  </div>
</div>
`;

return {
  json: {
    ...dadosCruzados,
    mensagem_gerada: mensagemFinal,
    email_html: emailHtml,
    status_envio: 'Pronto para disparo'
  }
};

